inline ::flatbuffers::Offset<SamplingOverrides> CreateSamplingOverrides(
    ::flatbuffers::FlatBufferBuilder &_fbb,
    ::flatbuffers::Optional<float> temperature = ::flatbuffers::nullopt,
    ::flatbuffers::Optional<float> top_p = ::flatbuffers::nullopt,
    ::flatbuffers::Optional<int32_t> top_k = ::flatbuffers::nullopt,
    ::flatbuffers::Optional<float> min_p = ::flatbuffers::nullopt,
    ::flatbuffers::Optional<int32_t> max_tokens = ::flatbuffers::nullopt,
    ::flatbuffers::Optional<int32_t> seed = ::flatbuffers::nullopt,
    ::flatbuffers::Optional<float> repeat_penalty = ::flatbuffers::nullopt,
    ::flatbuffers::Optional<float> presence_penalty = ::flatbuffers::nullopt,
    ::flatbuffers::Optional<float> frequency_penalty = ::flatbuffers::nullopt) {
  SamplingOverridesBuilder builder_(_fbb);
  if(frequency_penalty) { builder_.add_frequency_penalty(*frequency_penalty); }
  if(presence_penalty) { builder_.add_presence_penalty(*presence_penalty); }
  if(repeat_penalty) { builder_.add_repeat_penalty(*repeat_penalty); }
  if(seed) { builder_.add_seed(*seed); }
  if(max_tokens) { builder_.add_max_tokens(*max_tokens); }
  if(min_p) { builder_.add_min_p(*min_p); }
  if(top_k) { builder_.add_top_k(*top_k); }
  if(top_p) { builder_.add_top_p(*top_p); }
  if(temperature) { builder_.add_temperature(*temperature); }
  return builder_.Finish();
}

