  /// RoundRobin (each in turn).
  Tryll::CannedResponseSelectionStrategy selection_strategy() const {
    return static_cast<Tryll::CannedResponseSelectionStrategy>(GetField<uint8_t>(VT_SELECTION_STRATEGY, 2));
  }
