  CannedResponseParamsT *UnPack(const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
  void UnPackTo(CannedResponseParamsT *_o, const ::flatbuffers::resolver_function_t *_resolver = nullptr) const;
